entries[32137] = { ["name"] = "Verderbtes Totem der Lüfte", ["text"] = "125 Mana\nSofort\nBeschwört für 1 Min. ein Totem des heilenden Flusses mit 5 Gesundheit zu Füßen des Zaubernden, das Gruppenmitglieder im Umkreis von 0 Metern alle 5.2 Sek. um 5 heilt." }
