entries[32235] = { ["name"] = "Goldener Greif", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren goldenen Greifen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"In Sturmwind sind sie verrückt nach Löwen, und der Greif ist zur Hälfte ein Löwe. Das muss natürlich nicht heißen, dass ihnen beide Hälften zusagen. - Greifenmeister Krallenaxt\"\nVerkäufer:\nTannec Steinschnabel\nZone:\nSturmwind\nKosten:\n50" }
entries[32239] = { ["name"] = "Schwarzer Greif", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren schwarzen Greifen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"In Sturmwind sind sie verrückt nach Löwen, und der Greif ist zur Hälfte ein Löwe. Das muss natürlich nicht heißen, dass ihnen beide Hälften zusagen. - Greifenmeister Krallenaxt\"\nVerkäufer:\nTannec Steinschnabel\nZone:\nSturmwind\nKosten:\n50" }
entries[32240] = { ["name"] = "Weißer Greif", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren weißen Greifen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"In Sturmwind sind sie verrückt nach Löwen, und der Greif ist zur Hälfte ein Löwe. Das muss natürlich nicht heißen, dass ihnen beide Hälften zusagen. - Greifenmeister Krallenaxt\"\nVerkäufer:\nTannec Steinschnabel\nZone:\nSturmwind\nKosten:\n50" }
entries[32241] = { ["name"] = "Furcht", ["text"] = "30 Meter Reichweite\nSofort\nVersetzt einen Gegner in Angst und Schrecken, woraufhin er 6 Sek. lang verängstigt flieht. Es kann immer nur jeweils ein einzelnes Ziel in Angst und Schrecken versetzt werden." }
entries[32242] = { ["name"] = "Schneller blauer Greif", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren schnellen blauen Greifen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"Die Horde hatte Drachen und wir hatten Greifen. Diesen Krieg haben wir gewonnen. - Ilsa Trubelbräu\"\nVerkäufer:\nTannec Steinschnabel\nZone:\nSturmwind\nKosten:\n50" }
entries[32243] = { ["name"] = "Lohfarbener Windreiter", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren lohfarbenen Windreiter oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"Seit sie von Cairne und Thrall aus den Klauen der bösartigen Harpyien befreit wurden, wurden viele dieser Wesen zu wertvollen Gefährten der Horde.\"\nVerkäufer:\nDrakma\nZone:\nOrgrimmar\nKosten:\n50" }
