entries[32289] = { ["name"] = "Schneller roter Greif", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren schnellen roten Greifen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"Die Horde hatte Drachen und wir hatten Greifen. Diesen Krieg haben wir gewonnen. - Ilsa Trubelbräu\"\nVerkäufer:\nTannec Steinschnabel\nZone:\nSturmwind\nKosten:\n50" }
