entries[32379] = { ["name"] = "Schattenwort: Tod", ["text"] = "0.5% von Grundmana 40 Meter Reichweite\nSofort 10 sek. Abklingzeit\n1 Aufladung\nDisziplin, Heilig\nEin Wort der bindenden Dunkelheit, das Eurem Ziel (85% der Zaubermacht) Schattenschaden zufügt. Wenn Euer Ziel durch 'Schattenwort: Tod' nicht stirbt, erleidet Ihr Schaden in Höhe von 5% Eurer maximalen Gesundheit.\n\nDer Schaden wird gegen Ziele unter 20% Gesundheit um 150% erhöht.\n\nSchatten\nEin Wort der bindenden Dunkelheit, das Eurem Ziel (85% der Zaubermacht) Schattenschaden zufügt. Wenn Euer Ziel durch 'Schattenwort: Tod' nicht stirbt, erleidet Ihr Schaden in Höhe von 5% Eurer maximalen Gesundheit.\n\nDer Schaden wird gegen Ziele unter 20% Gesundheit um 150% erhöht.\n\nErzeugt 1 Wahnsinn." }
