entries[32390] = { ["name"] = "Schattenumschlingung", ["text"] = "Unbegrenzte Reichweite\nSofort\n[ Seelendieb : 'Seelendieb' / 'Schattenblitz'] wendet 'Schattenumschlingung' an, was Euren dem Ziel zugefügten Schaden 16 Sek. lang um [ Seelendieb : 2% / 4%] erhöht. Bis zu [ Seelendieb : 4 / 2]-mal stapelbar." }
