entries[32498] = { ["name"] = "Gürtel des Teufelspirschers", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSchweres Knotenhautleder (6), Dämonenhautleder (4), Kristalldurchströmtes Leder (8), Urluft (6), Runenfaden (2)\nOptionale Reagenzien:\n[] (#48)\nVerkäufer:\nRüstmeister Urgronn\nZone:\nHöllenfeuerhalbinsel\nThrallmar - Freundlich\nKosten:\n12\n\nGürtel des Teufelspirschers\nWird beim Anlegen gebunden\nTaille Kette\n5 Rüstung\n+3 [Beweglichkeit oder Intelligenz]+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\n\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 2 Ausdauer\n\nHaltbarkeit 50 / 50\n27\n\nRüstung des Teufelspirschers (0/3)\nBenötigt Lederverarbeitung der Scherbenwelt\n(50) Gürtel des Teufelspirschers\nArmschienen des Teufelspirschers\nBrustplatte des Teufelspirschers" }
entries[32499] = { ["name"] = "Armschienen des Teufelspirschers", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSchweres Knotenhautleder (6), Dämonenhautleder (6), Kristalldurchströmtes Leder (6), Urluft (4), Runenfaden (2)\nOptionale Reagenzien:\n[] (#49)\nVerkäufer:\nRüstmeister Urgronn\nZone:\nHöllenfeuerhalbinsel\nThrallmar - Wohlwollend\nKosten:\n16\n\nArmschienen des Teufelspirschers\nWird beim Anlegen gebunden\nHandgelenk Kette\n5 Rüstung\n+2 [Beweglichkeit oder Intelligenz]+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\n\nPrismatischer Sockel\nSockelbonus: + 1 Ausdauer\n\nHaltbarkeit 50 / 50\n27\n\nRüstung des Teufelspirschers (0/3)\nBenötigt Lederverarbeitung der Scherbenwelt\n(50) Gürtel des Teufelspirschers\nArmschienen des Teufelspirschers\nBrustplatte des Teufelspirschers" }
entries[32500] = { ["name"] = "Brustplatte des Teufelspirschers", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSchweres Knotenhautleder (10), Dämonenhautleder (4), Kristalldurchströmtes Leder (8), Urluft (8), Runenfaden (2)\nOptionale Reagenzien:\n[] (#49)\nVerkäufer:\nRüstmeister Urgronn\nZone:\nHöllenfeuerhalbinsel\nThrallmar - Wohlwollend\nKosten:\n16\n\nBrustplatte des Teufelspirschers\nWird beim Anlegen gebunden\nBrust Kette\n10 Rüstung\n+3 [Beweglichkeit oder Intelligenz]+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\n\nPrismatischer Sockel\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 2 Ausdauer\n\nHaltbarkeit 140 / 140\n27\n\nRüstung des Teufelspirschers (0/3)\nBenötigt Lederverarbeitung der Scherbenwelt\n(50) Gürtel des Teufelspirschers\nArmschienen des Teufelspirschers\nBrustplatte des Teufelspirschers" }
