entries[32546] = { ["name"] = "Verbindende Heilung", ["text"] = "3.4% von Grundmana 40 Meter Reichweite\nWirken in 1.5 sek.\nHeilt Euch, Euer Ziel und ein weiteres verbündetes Ziel innerhalb von 20 Metern um (94% der Zaubermacht) Gesundheit.\n\nVerringert die verbleibende Abklingzeit von 'Segenswort: Epiphanie' und 'Segenswort: Heiligung' um 3 Sek." }
