entries[32578] = { ["name"] = "Gor'dreks Salbe", ["text"] = "20 Meter Reichweite\nWirken in 5 sek.\nLässt einen Terrorwolf der Donnerfürsten wachsen und erhöht 1.5 Min. lang den von ihm verursachten Schaden. Dennoch besteht eine Chance, dass der Wolf aggressiv wird und sich gegen Euch wendet. Es kann immer nur ein Zauber dieser Art zur selben Zeit auf einem Wolf aktiv sein." }
entries[32580] = { ["name"] = "Heimtückischer mächtiger Fetisch", ["text"] = "20 Meter Reichweite\nWirken in 5 sek.\nBeschwört einen bösen Geist. Nachdem dieser besiegt wurde, verflucht er ein Ogerbauwerk im Wehr der Speerspießer oder im Außenposten der Blutschläger." }
