entries[32682] = { ["name"] = "Fluch der dunklen Kralle", ["text"] = "Nahkampfreichweite\nWirken in 2 sek.\nVerflucht einen Gegner 30 Sek. lang, erhöht erlittenen körperlichen Schaden um 14 und verringert die Ausdauer um 24. Das verfluchte Ziel hat eine Chance von 10%, dessen aktuellem Ziel Blutungsschaden zuzufügen.\n(Procchance: 10%)" }
