entries[32765] = { ["name"] = "Transmutieren: Erdsturmdiamant", ["text"] = "Wirken in 3 sek.\nTools: Stein der Weisen\nReagenzien:\nTiefenperidot (3), Schattendraenit (3), Golddraenit (3), Urerde (2), Urwasser (2)\nTransmutiert Edelsteine und Elementarkräfte in einen Erdsturmdiamanten.\nVerkäufer:\nFedryen Flinkspeer\nZone:\nZangarmarschen\nExpedition des Cenarius - Wohlwollend\nKosten:\n8\n\nErdsturmdiamant\nHandwerksmaterial" }
