entries[33095] = { ["name"] = "Angeln", ["text"] = "5 Meter ReichweiteKanalisiert 0.25 sek. Abklingzeit\nNehmt eine Angelrute zur Hand und sucht Euch ein Gewässer zum Angeln. Klickt mit der rechten Maustaste auf den Schwimmer im Wasser, wenn sich dieser bewegt, um den Fisch zu fangen. Eine höhere Fertigkeit verbessert Eure Chance auf einen erfolgreichen Fang in höherstufigen Gebieten." }
