entries[33110] = { ["name"] = "Gebet der Besserung", ["text"] = "Unbegrenzte Reichweite\nSofort\nBelegt einen Verbündeten mit einem Zauberschutz, der ihn um (61% der Zaubermacht) Gesundheit heilt, wenn er das nächste Mal Schaden erleidet. Anschließend springt der Schutz auf einen anderen Verbündeten innerhalb von 30 Metern über. Springt bis zu 4-mal und hält nach jedem Sprung 30 Sek. lang an." }
entries[33111] = { ["name"] = "Teufelskraft", ["text"] = "8 Meter Reichweite\nWirken in 3 sek.\nKanalisiert Teufelskraft auf das Ziel, erhöht die Größe um 25% und den verursachten körperlichen Schaden um 25." }
