entries[33130] = { ["name"] = "Todesmantel", ["text"] = "565 Mana 30 Meter Reichweite\nSofort\nVerursacht (21.4% der Zaubermacht) Schattenschaden und das betroffene Ziel läuft 3 Sek. lang voller Entsetzen davon. Der Zaubernde erhält 100% des verursachten Schadens in Gesundheit." }
